import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import BookingForm from "../components/BookingForm";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectModal from "../components/RejectModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";
 
const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();
  const { incharges, fetchInitialData } = useAppContext();
  const currentUser = useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem("user") || "{}");
    } catch {
      return {};
    }
  }, []);

  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
  });

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);

  const [showIncharges, setShowIncharges] = useState(false);
  const [cancelBookingId, setCancelBookingId] = useState(null);

  // ✅ FORM STATE
  const [formData, setFormData] = useState({
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: currentUser.username || "",
    department: currentUser.department || "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    purpose: "",
  });
  const [bookingLoading, setBookingLoading] = useState(false);
  const [availabilityMsg, setAvailabilityMsg] = useState("");

  const getApiError = (err, fallback) => {
    const detail = err.response?.data?.detail;
    if (Array.isArray(detail)) {
      return detail.map((item) => item.msg).join(", ");
    }
    if (typeof detail === "object" && detail) {
      return JSON.stringify(detail);
    }
    return detail || err.response?.data?.message || err.message || fallback;
  };

  const validateBookingForm = () => {
    if (formData.resourceScope === "block" && !formData.blockId) {
      return "Please select a block.";
    }
    if (!formData.resourceId) {
      return "Please select a resource.";
    }
    if (!formData.bookingDate) {
      return "Please select a booking date.";
    }
    if (!formData.startTime || !formData.endTime) {
      return "Please select both start and end time.";
    }
    if (formData.endTime <= formData.startTime) {
      return "End time must be after start time.";
    }
    if (!formData.purpose.trim()) {
      return "Purpose is required.";
    }
    return "";
  };

  const buildBookingPayload = () => ({
    block_id: formData.resourceScope === "block" ? Number(formData.blockId) : null,
    resource_id: Number(formData.resourceId),
    name: formData.name?.trim() || currentUser.username || "",
    department: formData.department?.trim() || null,
    booking_date: formData.bookingDate,
    start_time: formData.startTime,
    end_time: formData.endTime,
    purpose: formData.purpose.trim(),
  });

  // ✅ HANDLERS
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationError = validateBookingForm();
    if (validationError) {
      setAvailabilityMsg({ type: "error", message: validationError });
      return;
    }

    try {
      setBookingLoading(true);
      setAvailabilityMsg("");
      const res = await api.post("/client/bookings", buildBookingPayload());
      const createdBooking = res.data?.booking || res.data;
      setAvailabilityMsg({
        type: "success",
        message: res.data?.message || "Booking request submitted successfully",
      });
      setBookings((prev) => [createdBooking, ...prev]);
      setFormData((prev) => ({
        ...prev,
        resourceId: "",
        bookingDate: "",
        startTime: "",
        endTime: "",
        purpose: "",
      }));
      await fetchDashboard();
    } catch (err) {
      setAvailabilityMsg({
        type: "error",
        message: getApiError(err, "Booking request failed."),
      });
    } finally {
      setBookingLoading(false);
    }
  };

  const handleAvailabilityCheck = async () => {
    const validationError = validateBookingForm();
    if (validationError) {
      setAvailabilityMsg({ type: "error", message: validationError });
      return;
    }

    try {
      setAvailabilityMsg({ type: "info", message: "Checking availability..." });
      const res = await api.post("/client/availability", buildBookingPayload());
      setAvailabilityMsg({
        type: res.data.available ? "success" : "error",
        message: res.data.available
          ? "Resource is available for the selected slot."
          : res.data.message || "Resource is not available for the selected slot.",
      });
    } catch (err) {
      setAvailabilityMsg({
        type: "error",
        message: getApiError(err, "Availability check failed."),
      });
    }
  };

  // ✅ MENU
  const menuItems = useMemo(
    () => [
      { key: "overview", label: "Overview", to: "/", icon: "🏠" },
      {
        key: "new-booking",
        label: "New Booking",
        to: "/new-booking",
        icon: "➕",
      },
      {
        key: "my-bookings",
        label: "My Bookings",
        to: "/my-bookings",
        icon: "📋",
      },
      { key: "incharges", label: "Incharges", icon: "👨‍💼" },
    ],
    [],
  );

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  // 🔥 FINAL FETCH FIX
  const fetchDashboard = useCallback(async () => {
    try {
      setLoading(true);

      const res = await api.get("/client/bookings");
      const data = Array.isArray(res.data) ? res.data : res.data?.data || [];

      setBookings(data);

      const getStatus = (b) =>
        (b.status || b.booking_status || "").toLowerCase();

      const statsData = {
        total: data.length,
        pending: data.filter((b) => getStatus(b) === "pending").length,
        approved: data.filter((b) => getStatus(b) === "approved").length,
        rejected: data.filter((b) => getStatus(b) === "rejected").length,
      };

      setStats(statsData);
      setError("");
    } catch (err) {
      console.log(err);
      setError("Failed to load data");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboard();
    fetchInitialData?.();
  }, [fetchDashboard, fetchInitialData]);

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
    setRefreshing(false);
  };

  const handleCancel = (id) => setCancelBookingId(id);

  const handleCancelSubmit = async (reason) => {
    try {
      await api.post(`/client/bookings/${cancelBookingId}/cancel`, { reason });
      setCancelBookingId(null);
      fetchDashboard();
    } catch (err) {
      setError(getApiError(err, "Cancel failed"));
    }
  };

  const recentBookings = useMemo(() => bookings.slice(0, 3), [bookings]);

  // 🔥 VIEW RENDER
  const renderContent = () => {
    switch (view) {
      case "new-booking":
        return (
          <BookingForm
            formData={formData}
            onChange={handleChange}
            onSubmit={handleSubmit}
            onAvailabilityCheck={handleAvailabilityCheck}
            availabilityMsg={availabilityMsg}
            loading={bookingLoading}
          />
        );

      case "my-bookings":
        return (
          <BookingList
            title="My Bookings"
            bookings={bookings}
            onCancel={handleCancel}
          />
        );

      default:
        return (
          <>
            {/* ✅ STATS */}
            <section className="stats-grid">
              <div className="card total">
                <p>Total</p>  
                <h2>{stats.total}</h2>
              </div>

              <div className="card pending">
                <p>Pending</p>
                <h2>{stats.pending}</h2>
              </div>

              <div className="card approved">
                <p>Approved</p>
                <h2>{stats.approved}</h2>
              </div>

              <div className="card rejected">
                <p>Rejected</p>
                <h2>{stats.rejected}</h2>
              </div>
            </section>

            <BookingList
              title="Recent Bookings"
              bookings={recentBookings}
              onCancel={handleCancel}
            />
          </>
        );
    }
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={menuItems}
        onLogout={handleLogout}
        onSelect={(key) => key === "incharges" && setShowIncharges(true)}
      />

      <main className="dashboard-main">
        <Navbar
          title="Client Dashboard"
          onRefresh={handleRefresh}
          refreshing={refreshing}
        /> 

        {error && <div className="error-box">{error}</div>}

        {loading ? <p>Loading...</p> : renderContent()}
      </main>

      <InchargeModal
        open={showIncharges}
        groups={incharges}
        onClose={() => setShowIncharges(false)}
      />

      <RejectModal
        open={Boolean(cancelBookingId)}
        onClose={() => setCancelBookingId(null)}
        onSubmit={handleCancelSubmit}
      />
    </div>
  );
};

export default ClientDashboard;
